import type { ToolbarProps } from "./toolbar.types";
import type { CSSObject, Theme } from "@emotion/react";
import type { ComponentStyleVariantConfig } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
import * as RadixToolbar from "@radix-ui/react-toolbar";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Toolbar";

// Generate child element class names for the component, should match available style slots
export const ToolbarClasses = {
  root: "exp-textura_toolbar",
  leading: "exp-textura_toolbar_leading",
  trailing: "exp-textura_toolbar_trailing",
  item: "exp-textura_toolbar_item",
  divider: "exp-textura_toolbar_divider",
  toggleGroup: "exp-textura_toolbar_toggle_group",
  toggleItem: "exp-textura_toolbar_toggle_item",
  group: "exp-textura_toolbar_group",
};

// Set up style variant settings for the component
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  floating: {
    root: {
      backgroundColor: theme.color.background.default,
      padding: theme.toRem(theme.spacing[4]),
      borderRadius: theme.toRem(theme.border.radius.sm),
      boxShadow: theme.dropShadow.md,
      border: `${theme.toRem(1)} solid ${theme.color.border.default}`,
    },
  },
  "rte-default": {
    root: {
      gap: theme.toRem(theme.spacing[8]),
    },
    leading: {
      gap: theme.toRem(theme.spacing[8]),
    },
    trailing: {
      gap: theme.toRem(theme.spacing[8]),
    },
    divider: {
      height: theme.toRem(32),
    },
  },
  "rte-floating": {
    root: {
      gap: theme.toRem(theme.spacing[8]),
      backgroundColor: theme.color.background.default,
      padding: theme.toRem(theme.spacing[4]),
      borderRadius: theme.toRem(theme.border.radius.sm),
      boxShadow: theme.dropShadow.md,
      border: `${theme.toRem(1)} solid ${theme.color.border.default}`,
      width: "fit-content",
    },
    leading: {
      gap: theme.toRem(theme.spacing[8]),
    },
    trailing: {
      gap: theme.toRem(theme.spacing[8]),
    },
    divider: {
      height: theme.toRem(32),
    },
  },
});

const generateStyles = (props: ToolbarProps): CSSObject => {
  const { currentTheme: theme, variant = "default", styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ToolbarProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
    width: "100%",
    gap: theme.toRem(theme.spacing[16]),
    boxSizing: "border-box",
    backgroundColor: "transparent",
    padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,
    border: "none",
    borderBottom: `${theme.toRem(theme.divider.default.border.width)} solid ${theme.divider.default.color.default}`,
    boxShadow: "none",
    overflow: "scroll",
    scrollbarWidth: "none",

    [`.${ToolbarClasses.leading}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[16]),
      marginInlineEnd: "auto",
      ...styleSlots?.leading,
    },

    [`.${ToolbarClasses.trailing}`]: {
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[16]),
      marginInlineStart: "auto",
      ...styleSlots?.trailing,
    },

    [`.${ToolbarClasses.divider}[data-orientation="vertical"]`]: {
      height: theme.toRem(24),
      ...styleSlots?.divider,
    },

    [`.${ToolbarClasses.item}`]: {
      ...styleSlots?.item,
    },

    [`.${ToolbarClasses.group}`]: {
      ...styleSlots?.group,
    },

    [`.${ToolbarClasses.toggleGroup}`]: {
      ...styleSlots?.toggleGroup,
    },

    [`.${ToolbarClasses.toggleItem}`]: {
      ...styleSlots?.toggleItem,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
// Using RadixToolbar.Root as the base component
export const StyledToolbar = styled(RadixToolbar.Root, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ToolbarProps>((props) => generateStyles(props));
